<?php
/**
 * `GET /bcm/v1/products/{id}/variations` (SPEC §4.2, §8, §12.1): one page of
 * a product's variations, fetched when the grid expands a variable row.
 * Its arguments (the id, paging and `fields[]`) and its item schema are
 * generated by RouteSchema, with `per_page` capped at 100 like every read.
 *
 * The page goes through Query\Catalogue like the grid's own: ProductQuery in
 * the variations mode restricted to the product, published and private
 * variations in WooCommerce's order (`menu_order`, then id), hydrated without
 * instantiating a product. Each item carries the variation's registry fields,
 * `parent_id`, `parent_name` and `attribute_summary` ("Blue / Large").
 *
 * A product with no variations answers 200 with no items; an id that is not
 * a product — missing, a variation, any other post type or trashed —
 * answers 404 `bcm_not_found` before any catalogue query.
 *
 * @package BulkCatalogueManager
 * @license GPL-3.0-or-later
 */

declare( strict_types = 1 );

namespace BulkCatalogueManager\Rest;

use BulkCatalogueManager\Fields\Registry;
use BulkCatalogueManager\Query\Catalogue;
use BulkCatalogueManager\Query\Criteria;
use BulkCatalogueManager\Query\Hydrator;
use BulkCatalogueManager\Query\ProductQuery;

defined( 'ABSPATH' ) || exit;

/**
 * The variations route.
 */
final class VariationsController implements ReadController {
	/**
	 * The route, under Access::REST_NAMESPACE.
	 */
	public const ROUTE = '/products/(?P<id>[\d]+)/variations';

	/**
	 * The item schema's title.
	 */
	public const TITLE = 'bcm-variation';

	/**
	 * Refusal code for an id that is not a product.
	 */
	public const NOT_FOUND = 'bcm_not_found';

	/**
	 * Arguments and schema generator.
	 *
	 * @var RouteSchema
	 */
	private RouteSchema $schema;

	/**
	 * The cached page reader.
	 *
	 * @var Catalogue
	 */
	private Catalogue $catalogue;

	/**
	 * Build over a registry.
	 *
	 * @param Registry $registry Field registry.
	 */
	public function __construct( Registry $registry ) {
		$this->schema    = new RouteSchema( $registry );
		$this->catalogue = new Catalogue( new Hydrator( $registry ) );
	}

	/**
	 * Add the route through the registrar.
	 *
	 * @param Routes $routes The registrar.
	 */
	public function register_routes( Routes $routes ): void {
		$routes->add(
			self::ROUTE,
			[
				[
					'methods'             => 'GET',
					'callback'            => [ $this, 'get_items' ],
					'permission_callback' => [ Access::class, 'can_read' ],
					'args'                => $this->schema->variation_args(),
				],
				'schema' => [ $this, 'get_item_schema' ],
			]
		);
	}

	/**
	 * One page of a product's variations: `{ items, pagination }`.
	 *
	 * @param \WP_REST_Request $request The validated, sanitised request.
	 */
	public function get_items( \WP_REST_Request $request ): \WP_REST_Response|\WP_Error {
		$id      = (int) $request->get_param( 'id' );
		$product = $id > 0 ? get_post( $id ) : null;
		if ( ! is_object( $product ) || 'product' !== ( $product->post_type ?? '' ) || ! in_array( $product->post_status ?? '', ProductQuery::STATUSES, true ) ) {
			return Refusal::create(
				self::NOT_FOUND,
				__( 'That product could not be found. It may have been deleted; reload the list and try again.', 'bulk-catalogue-manager-for-woocommerce' ),
				404
			);
		}

		$criteria = Criteria::from_array(
			[
				'mode'     => Criteria::MODE_VARIATIONS,
				'parent'   => $id,
				'page'     => $request->get_param( 'page' ) ?? 1,
				'per_page' => $request->get_param( 'per_page' ) ?? Criteria::DEFAULT_PER_PAGE,
			]
		);
		$fields   = $request->get_param( 'fields' );
		return ProductsController::response( $criteria, $this->catalogue->page( $criteria, is_array( $fields ) ? array_values( array_filter( $fields, 'is_string' ) ) : [] ) );
	}

	/**
	 * The schema of one variation row, generated from the registry.
	 *
	 * @return array<string, mixed>
	 */
	public function get_item_schema(): array {
		return $this->schema->item_schema( self::TITLE, RouteSchema::row_extras() );
	}
}
